import { test } from 'node:test';
import assert from 'node:assert/strict';
import { criarCanalPrincipal, criarWorkerSimulado } from './solution.mjs';

test('o worker devolve o resultado do trabalho', async () => {
  const canal = criarCanalPrincipal();
  const worker = criarWorkerSimulado((dado) => dado * 2, canal);

  const resposta = new Promise((resolve) => canal.receber(resolve));
  worker.enviar(21);

  assert.equal(await resposta, 42);
});

test('o worker também devolve o resultado de um trabalho assíncrono', async () => {
  const canal = criarCanalPrincipal();
  const worker = criarWorkerSimulado(async (dado) => dado + 100, canal);

  const resposta = new Promise((resolve) => canal.receber(resolve));
  worker.enviar(5);

  assert.equal(await resposta, 105);
});

test('lança erro em entradas inválidas', () => {
  assert.throws(() => criarWorkerSimulado('trabalho', { enviar() {} }), /função/);
  assert.throws(() => criarWorkerSimulado((dado) => dado, {}), /canal/);
});

test('o canal principal entrega a mensagem a TODOS os ouvintes', () => {
  const canal = criarCanalPrincipal();
  const recebidas = [];
  canal.receber((msg) => recebidas.push(msg));
  canal.receber((msg) => recebidas.push(msg + '!'));
  canal.enviar('oi');

  assert.deepEqual(recebidas, ['oi', 'oi!']);
});

