export function criarCanalPrincipal() {
  const ouvintes = [];

  function receber(ouvinte) {
    if (typeof ouvinte !== 'function') {
      throw new Error('ouvinte precisa ser uma função');
    }
    ouvintes.push(ouvinte);
  }

  function enviar(mensagem) {
    for (const ouvinte of ouvintes) {
      ouvinte(mensagem);
    }
  }

  return { receber, enviar };
}

export function criarWorkerSimulado(funcaoDeTrabalho, canal) {
  if (typeof funcaoDeTrabalho !== 'function') {
    throw new Error('funcaoDeTrabalho precisa ser uma função');
  }
  if (!canal || typeof canal.enviar !== 'function') {
    throw new Error('canal precisa ter uma função enviar');
  }

  return {
    enviar(dado) {
      // Simula o worker: processa a mensagem (talvez assíncrono)
      // e devolve o resultado pelo canal, como um postMessage de volta.
      Promise.resolve(funcaoDeTrabalho(dado)).then((resultado) => {
        canal.enviar(resultado);
      });
    },
  };
}
